  describe('deprecated prop `small`', () => {
    const wrapper = shallow(<Button size="sm" className="extra-class" />);

    it('has the expected classes for small', () => {
      expect(wrapper.hasClass(`${prefix}--btn--sm`)).toEqual(true);
    });

